/* prog25_balanced_multitype.c
 *
 * Reimplementation of the original binary's behaviour.
 * The program reads the first command‑line argument (or an empty string
 * when none is supplied) and checks whether the characters '(', ')',
 * '[', ']', '{', '}' are correctly balanced and properly nested.
 * It prints either "BALANCED" or "UNBALANCED" to stdout.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdbool.h>

/* Returns true if the opening bracket `open` matches the closing bracket `close`. */
static bool matches(char open, char close)
{
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

/* Checks whether `s` contains a balanced sequence of the three bracket types. */
static bool is_balanced(const char *s)
{
    size_t len = strlen(s);
    /* The stack never needs to be larger than the input length. */
    char *stack = malloc(len);
    if (!stack) {
        /* In the unlikely event of allocation failure, treat as unbalanced. */
        return false;
    }

    size_t top = 0;          /* Number of elements currently on the stack */
    bool ok = true;          /* Becomes false on the first mismatch */

    for (size_t i = 0; i < len && ok; ++i) {
        char c = s[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                stack[top++] = c;               /* push */
                break;

            case ')':
            case ']':
            case '}':
                if (top == 0) {                 /* nothing to match */
                    ok = false;
                } else {
                    char open = stack[--top];    /* pop */
                    if (!matches(open, c))
                        ok = false;
                }
                break;

            default:
                /* All other characters are ignored. */
                break;
        }
    }

    /* Balanced only if no mismatch occurred and the stack is empty. */
    ok = ok && (top == 0);
    free(stack);
    return ok;
}

int main(int argc, char *argv[])
{
    const char *input = (argc >= 2) ? argv[1] : "";
    if (is_balanced(input))
        puts("BALANCED");
    else
        puts("UNBALANCED");
    return 0;
}
